// Datei prüfen: Herkunft und Sitzung wie bei ALLY 8, Datei aus dem Formular lesen.
// Logo und Bildmarke (Seite Unternehmen): die Datenbank prüft Recht, Typ (SVG oder PNG) und Größe (höchstens 500 KB).
// Eigene Hintergründe (Seite Marketing, Gestaltung): die Datenbank prüft Recht, Paket, Typ (JPG oder PNG), Größe (höchstens 1 MB) und Anzahl.
// Dieser Ablauf speichert keine Ausführungsdaten.
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($input.first().json.headers || {}).host || '').trim().toLowerCase());
const item = $input.first();
const h = item.json.headers || {};
const b = item.json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// Verweis nur mit Trennzeichen nach dem Seitenpfad (Ende, '/', '?' oder '#'), sonst gälte auch /webhook/web-xyz (Stefan 17.10.2026)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
const ARTEN = ['logo_fuer_dunkel', 'logo_fuer_hell', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell', 'hintergrund'];
const aktion = herkunftOk ? 'speichern' : 'ungueltig';
const id = /^[0-9]{1,9}$/.test(s(b.id)) ? s(b.id) : '';
const art = ARTEN.includes(s(b.art)) ? s(b.art) : '';
const istHg = art === 'hintergrund';
const GRENZE = istHg ? 1048576 : 512000;
let b64 = '', name = '';
const bin = item.binary || {};
const schluessel = Object.keys(bin).find(k => k === 'datei') || Object.keys(bin).find(k => k.startsWith('datei'));
if (aktion === 'speichern' && schluessel) {
  const puffer = await this.helpers.getBinaryDataBuffer(0, schluessel);
  name = s(bin[schluessel].fileName).slice(0, 200);
  // Zu große Dateien nur angeschnitten weitergeben: die Datenbank erkennt die Überschreitung und meldet sie
  if (puffer.length > 0) b64 = puffer.subarray(0, GRENZE + 1).toString('base64');
}
const daten = { id, art, name, b64 };
if (istHg) {
  daten.helligkeit = ['hell', 'dunkel'].includes(s(b.helligkeit)) ? s(b.helligkeit) : '';
  // Kleine Vorschau, im Browser erzeugt; die Datenbank prüft Form und Größe
  const v = s(b.vorschau);
  daten.vorschau = v.length <= 60000 && /^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(v) ? v : '';
}
return [{ json: { token, aktion, id, art, daten: JSON.stringify(daten) } }];

// Zurück zur Seite: Logo und Bildmarke zum Unternehmen (Seite Unternehmen), Hintergründe zur Gestaltung (Seite Marketing).
// Sitzung wie bei ALLY 8 behandeln
const SEITE = '/webhook/web';
const F = $('Datei prüfen').first().json;
// Stelle auf der Seite (Stefan 17.10.2026): Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt
const ZQ = $('Datei-Upload').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const r = $input.first().json.r || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.aktion === 'ungueltig' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else {
  if (F.art === 'hintergrund') ziel = SEITE + '?ansicht=marketing' + (F.id ? '#gest-' + F.id : '');
  else ziel = SEITE + '?ansicht=unternehmen' + (F.id ? '&offen=' + F.id + '#cd-' + F.id : '');
  ziel = stelle(ziel);
  if (F.token) cookie = keks(F.token, 2592000);
}
return [{ json: { ziel, set_cookie: cookie } }];
